import{_ as o,o as r,c as e,a3 as a}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Anim-Director: A Large Multimodal Model Powered Agent for Controllable Animation Video Generation","description":"","frontmatter":{"title":"Anim-Director: A Large Multimodal Model Powered Agent for Controllable Animation Video Generation","arxiv":"2408.09787","date":"2024-08-19","authors":"Yunxin Li, Haoyuan Shi, Baotian Hu, Longyue Wang, Jiashun Zhu, Jinyi Xu, Zhen Zhao, Min Zhang","categories":"cs.CL, cs.CV, cs.MM","topics":"智能体视频生成, 免训练流水线, 自反思筛选","outline":[2,2]},"headers":[],"relativePath":"papers/2408.09787.md","filePath":"papers/2408.09787.md","lastUpdated":null}'),n={name:"papers/2408.09787.md"};function i(s,t,g,u,l,d){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="anim-director-a-large-multimodal-model-powered-agent-for-controllable-animation-video-generation" tabindex="-1">Anim-Director: A Large Multimodal Model Powered Agent for Controllable Animation Video Generation <a class="header-anchor" href="#anim-director-a-large-multimodal-model-powered-agent-for-controllable-animation-video-generation" aria-label="Permalink to &quot;Anim-Director: A Large Multimodal Model Powered Agent for Controllable Animation Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2408.09787" target="_blank" rel="noreferrer">2408.09787</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-08-19（SIGGRAPH Asia 2024）</td></tr><tr><td><strong>作者</strong></td><td>Yunxin Li, Haoyuan Shi, Baotian Hu, Longyue Wang, Jiashun Zhu, Jinyi Xu, Zhen Zhao, Min Zhang（哈工大深圳 / 吉林大学 / 上海 AI Lab）</td></tr><tr><td><strong>分类</strong></td><td>cs.CL, cs.CV, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>完全免训练：GPT-4 用九条固定指令把一句话故事扩写成剧本、给 Midjourney 写提示词、从 4 张候选图里挑一张并用 SAM 换角色、给 Pika 预测 JSON 超参、再从 10 段候选视频里经指标粗筛加 GPT-4 精选出一段。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><p>本页依据 <strong>v1</strong> 全文撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>2024 年中做动画生成的主流路线是训模型：TaleCrafter 训 Text-to-Layout 与 Controllable Layout-to-Image 两个模型，Make-A-Story 训一个带视觉记忆模块的自回归扩散框架。这条路线的毛病是要人工标注的动画数据、要训多个模型，且在 Pororo-SV、Flintstones 这类小数据集上训出来的模型<strong>换个新故事就不灵</strong>。</p><p>论文还指出一个更具体的失败模式：传统做法先把叙事转成五六句简单提示词，只传达角色关系与基本动作，<strong>跨句语义连贯性保不住</strong>。这篇把整件事交给 GPT-4 当导演，一行训练代码都不写，验证一个当时尚未被验证的命题：<strong>LMM 的理解、推理与&quot;看图判断好坏&quot;的能力，是否已足以替代那条需要训练的流水线</strong>。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>故事可视化的训练路线（StoryGAN、StoryDALL-E、Make-A-Story、AR-LDM、TaleCrafter）可控性逐步变好，但共同前提是有对应的动画数据集可训，对新叙事泛化差。</p><p>通用视频生成模型（ModelScope、SVD、VideoCrafter、DynamiCrafter、AnimateDiff）与商业工具（Gen-2、Pika）泛化强，但只解决&quot;一段几秒的片段&quot;，不解决&quot;一个故事分成多少镜头、每个镜头里谁在场&quot;。</p><p>LMM 驱动的 agent（Chameleon、Toolformer、Mobile-Agent）已证明大模型能调外部工具，但没有一个面向动画生产；论文声称自己是<strong>第一个用 LMM 构建动画视频生成自主 agent</strong> 的工作。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2024 年中有几个现成前提：GPT-4V 能看图并回答&quot;这张图符不符合这段描述&quot;；Midjourney 支持&quot;参考图 + 文本 → 图&quot;、Pika 支持&quot;图 + 文本 → 视频&quot;，即<strong>先验图像可以作为一致性载体</strong>，不需要训 LoRA；VBench 提供了现成的自动视频指标。</p><p>三者拼起来，免训练路径就浮现了：先用 LMM 把故事写细，再把角色与场景抽成列表并<strong>先单独生成角色图与场景图</strong>，之后每个镜头都以这些先验图为条件生成。剩下的问题是生成工具的随机性——既然 LMM 能看图判断，就把&quot;生成多个候选 + LMM 挑一个&quot;当作通用的质量提升手段。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>如果生成工具的<strong>平均质量</strong>不够但<strong>方差足够大</strong>，那么&quot;多采样 + 好的裁判&quot;就能把有效质量提上去，而这一步完全不需要训练。Anim-Director 把 LMM 同时用作编剧、提示词工程师、超参预测器和裁判，一致性则靠&quot;先画角色图、再让每个镜头以它为条件&quot;这个纯提示词层面的技巧维持。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以论文的例子 &quot;A cat and a dog are playing in the garden.&quot; 走一遍。工具栈：GPT-4 + Midjourney + Pika + SAM。</p><p><strong>Step #1 故事细化。</strong> 要求扩写到约 150 词、加入用双引号包裹的对白与情绪细节、<strong>保留原有角色名</strong>，并鼓励引入一个转折点。</p><p><strong>Step #2 剧本生成。</strong> 先抽角色与场景：<strong>&quot;任何多次出现的人或动物都算一个角色&quot;</strong>，场景统一写成 <code>名称（Indoor/Outdoor）:</code>。再按 <code>[包含的所有角色][包含的场景]: 本镜头描述</code> 生成分镜。最后自检：逐镜头核对角色与场景是否都在列表里、该出场的角色有没有漏，有问题回答 &quot;Yes.&quot; 并给出修订版。</p><p><strong>Step #3 场景图生成。</strong> 先用 Midjourney 以纯文本生成角色图与场景设定图作为<strong>先验视觉条件</strong>，再为每个镜头写提示词走 Text + Image → Image。指令里有两条很实在的约束：角色必须按规则重命名；<strong>镜头描述要简化角色间的动作与互动，避免过于复杂或难以图示的描述</strong>。</p><p><strong>Step #4 场景图改进。</strong> 生成 4 张候选，GPT-4 回答 &quot;The answer is image x&quot; 并给出分析。选出后再比对该图与先验角色图的一致性；不一致就用 <strong>SAM 分割 + Midjourney 区域替换</strong>换掉角色，结果回流重新检查直到通过。</p><p><strong>Step #5–6 视频生成与增强。</strong> GPT-4 写出分为 Screen Description 与 Action Description 的提示句，并<strong>预测 Pika 的超参</strong>（固定 JSON：<code>motion</code>、<code>guidanceScale</code>、<code>negativePrompt</code>，以及 camera 的 zoom / pan / tilt / rotate）。随后生成 <strong>10 个候选</strong>，先用自动指标（模糊检测、主体一致性、背景一致性）排序取前 3，再把每段视频压成&quot;含 5 个时间帧的拼图&quot;交给 GPT-4 挑一个，最后拼成成片并用 TTS 配音。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>数据与基线。</strong> 从 TinyStories 取 100 条简短叙事。图像侧对比 Custom Diffusion、DPT-T2I、Midjourney V6；视频侧对比 VideoCrafter1/2、TaleCrafter、ModelScope、AnimateDiff、SVD、DynamiCrafter、Vlogger、Gen-2、Pika-v2。</p><p><strong>成图质量。</strong>（Coherence / I-I Sim / T-I Sim）Custom-Diffusion 0.74 / 0.66 / 0.28；DPT-T2I 0.75 / 0.65 / 0.29；Midjourney-V6 0.76 / 0.69 / 0.28；本文 0.87 / 0.85 / 0.29；去掉图像改进 0.82 / 0.82 / 0.28。<strong>T-I Sim 一列所有模型都在 0.28–0.29，完全没有区分度</strong>；真正拉开差距的是角色跨图一致性 0.69 → 0.85。一处口径问题：论文说表 3 的 Coherence 采用视频评测里主体与背景一致性的平均分，而按视频表的 0.86 与 0.93 取平均得 0.895，与表 3 写的 0.87 对不上。</p><p><strong>视频质量。</strong>（V-Q / Subject / BackG / T-V / 平均时长秒）本文 0.74 / 0.86 / 0.93 / 0.19 / 35.0，去掉视频增强 0.67 / 0.84 / 0.91 / 0.18 / 35.0；基线最强项是 DynamiCrafter 的 V-Q 0.72、Gen-2 与 Pika-v2 的 0.82/0.88 与 0.82/0.90。本文四项均最好。关于时长要小心：正文说&quot;每条 prompt 生成 3 秒，VideoCrafter2 只有 1 秒&quot;指的是<strong>单镜头片段</strong>，而平均时长一列里 <strong>Gen-2 的 42.3 秒长于本文的 35.0 秒</strong>。</p><p><strong>消融的覆盖范围。</strong> 只做了两个：去掉图像改进（0.87 → 0.82）与去掉视频增强（0.74 → 0.67）。<strong>故事细化、剧本生成与自检、超参预测三处一个都没被消融</strong>，而这三处恰是&quot;LMM 当导演&quot;叙事的主体。全部结论来自自动指标，<strong>没有任何人工评测</strong>，也没有对 GPT-4 作为裁判的准确率做校准。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：Anim-Director 用九条固定指令让 GPT-4 串起 Midjourney、Pika 与 SAM，完成从一句话故事到成片动画的全流程，全程免训练。跨镜头一致性靠&quot;先单独生成角色图与场景图、再让每个镜头以它为条件&quot;，配合 SAM 分割与区域替换修补。质量提升靠自反思筛选：图像 4 选 1，视频先用自动指标 10 选 3 再由 GPT-4 精选。100 条 TinyStories 上角色跨图一致性从 0.69 提到 0.85，视频四项指标均最好。但只有筛选模块被消融验证，且全程没有人工评测与裁判校准。</p><p><strong>3 句话版</strong>：把动画生产完全外包给一个 LMM 加三个现成工具，不训练任何模型。一致性来自先验角色图，质量来自多采样加 LMM 筛选。定量增益集中在角色一致性，真正属于&quot;导演&quot;的那部分未被单独验证。</p><p><strong>1 句话版</strong>：当工具方差足够大时，一个会看图的裁判就能替代一条需要训练的流水线。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>GPT-4 判断&quot;哪张图更好、哪段视频动作更准&quot;的能力足够可靠，可以充当整条流水线的质量闸门</strong>。系统没有任何训练、没有可学习参数，全部质量提升都压在这个裁判上。</p><p>两处会失效：<strong>判断视频</strong>是把一段视频压成 5 张静态帧的拼图，丢掉了帧间连续性、速度与时序，而这恰是&quot;动作准不准&quot;的核心信息；<strong>判断图像一致性</strong>靠 GPT-4 比对场景图与角色图，而发型、服饰配色、面部特征的细微漂移正是多模态模型最容易看漏的差异。</p><p>论文提供的证据只有端到端指标的提升，<strong>没有任何对裁判本身的校准</strong>：没有报告 GPT-4 挑出的图与人类会挑的图一致率，也没有报告 4 选 1 随机挑的分数。缺少这两条，&quot;自反思筛选有效&quot;与&quot;多采样后取任意一个都更好&quot;就无法区分。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现整条流水线，只校准那个裁判。</p><ul><li>数据：30–50 条镜头描述，每条用同一个 T2I 工具生成 4 张候选图。</li><li>实现：三种选择策略——GPT-4 按原指令选、随机选、按 CLIP 文图相似度选；另请 2–3 位标注者在不知来源的情况下给出&quot;哪张最好&quot;的人工标签。</li><li>测量：三种策略与人工标签的一致率，以及最终的 I-I Sim 与 T-I Sim。</li><li>判据：若 GPT-4 与随机在最终指标上差距很小，说明增益来自多采样而非&quot;LMM 会挑&quot;；若与人工标签的一致率接近 25% 的随机基线，裁判就没有被证明可用。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>攻击一：选择指标与评测指标是同一个，构成循环。</strong> 这是本文最硬的问题。Step #6 明确写着先用&quot;模糊检测 + 主体一致性 + 背景一致性&quot;从 10 个候选里筛出前 3，而表 4 报告的正是 <strong>Subject 与 Background consistency</strong>。系统在测试时对着评测指标做了搜索，然后用同一指标宣布自己最好，而基线是单次采样的结果。公平的对照是给每个基线也做 best-of-10；论文没有做。</p><p><strong>攻击二：这些指标偏爱静止画面，且失败条件写在论文自己的提示词里。</strong> 主体与背景一致性度量帧间相似度，几乎不动的视频天然拿高分；表里没有任何反映运动幅度的指标（VBench 有 dynamic degree，论文没用），也没有<strong>把场景图直接静止播放 3 秒</strong>这个平凡基线。另一方面，指令明令&quot;简化角色间的动作与互动，避免过于复杂或难以图示的描述&quot;，等于承认工具处理不了复杂交互，并通过<strong>在上游阉割任务难度</strong>来规避；需要两个角色实质接触的情节会在剧本阶段被悄悄改写掉，最终指标不会下降，但<strong>用户要的故事没有被讲出来</strong>。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：这套系统的&quot;自反思&quot;是一个开环选择器——它从候选里挑一个，但从不知道自己挑得对不对，也没有机制积累&quot;我上次挑错了&quot;。论文把裁判当成可信的，却没有测量它。</p><p><strong>新的 framing</strong>：把 LMM-as-judge 从<strong>假定可靠的组件</strong>改造成<strong>需要先校准、并持续被监控的测量仪器</strong>。任何用 LMM 做筛选的流水线，都应先在一小批人工标注上测出裁判的准确率与偏好方向，把偏差写进论文，并在报告端到端指标时同时报告&quot;随机挑选&quot;的对照。这不是加模块，而是改变这类系统的<strong>证据标准</strong>。</p><p><strong>第一个实验</strong>：构造&quot;裁判压力测试集&quot;——对同一条镜头描述，人工制造若干组受控候选对，每对只在一个维度上有差异（服饰颜色改了 / 角色少了一个 / 动作方向反了 / 画面更亮），测 GPT-4 在每个维度上的判别准确率，产出&quot;裁判能看见什么&quot;的能力地图。若它对亮度敏感而对角色数量不敏感，就可推断这类流水线里&quot;一致性&quot;的提升有多少来自裁判偏好的系统性偏移。</p>',48)])])}const c=o(n,[["render",i]]);export{h as __pageData,c as default};
